#include "p7_config.h"

#include <string.h>

#include "easel.h"
#include "esl_random.h"
#include "esl_vectorops.h"

#include "hmmer.h"

P7_TRACE *
p7_trace_Create(void)
{
  P7_TRACE *tr = NULL;
  int       status;

  ESL_ALLOC(tr, sizeof(P7_TRACE));
  tr->st        = NULL;
  tr->pp        = NULL;
  tr->M         = 0;
  tr->L         = 0;
  tr->N         = 0;
  tr->nalloc    = 0;
  tr->ndom      = 0;
  tr->dom       = NULL;
  tr->dalloc    = 0;
  tr->is_multihit = TRUE;
  tr->parent    = NULL;

  return tr;

 ERROR:
  p7_trace_Destroy(tr);
  return NULL;
}

P7_TRACE *
p7_trace_CreateWithPP(void)
{
  int       status;
  P7_TRACE *tr = p7_trace_Create();
  if (tr == NULL) return NULL;

  ESL_ALLOC(tr->pp, sizeof(float) * p7_TRACE_ALLOCINC);
  return tr;

 ERROR:
  p7_trace_Destroy(tr);
  return NULL;
}

int
p7_trace_Grow(P7_TRACE *tr)
{
  void *tmp;
  int   new_nalloc = (tr->nalloc == 0) ? p7_TRACE_ALLOCINC : tr->nalloc * 2;
  int   status;

  ESL_RALLOC(tr->st, tmp, sizeof(int)   * new_nalloc);
  if (tr->pp != NULL) {
    ESL_RALLOC(tr->pp, tmp, sizeof(float) * new_nalloc);
  }
  tr->nalloc = new_nalloc;
  return eslOK;

 ERROR:
  return status;
}

int
p7_trace_GrowDomains(P7_TRACE *tr)
{
  void *tmp;
  int   new_dalloc = (tr->dalloc == 0) ? p7_TRACE_ALLOCINC : tr->dalloc * 2;
  int   status;

  ESL_RALLOC(tr->dom, tmp, sizeof(P7_DOM) * new_dalloc);
  tr->dalloc = new_dalloc;
  return eslOK;

 ERROR:
  return status;
}

int
p7_trace_Append(P7_TRACE *tr, int st, int k, int i)
{
  int status;

  if (tr->N == tr->nalloc) {
    if ((status = p7_trace_Grow(tr)) != eslOK) return status;
  }

  tr->st[tr->N] = st;
  tr->N++;
  return eslOK;
}

int
p7_trace_AppendWithPP(P7_TRACE *tr, int st, int k, int i, float postp)
{
  int status;

  if (tr->N == tr->nalloc) {
    if ((status = p7_trace_Grow(tr)) != eslOK) return status;
  }
  if (tr->pp == NULL) ESL_FAIL(eslEINVAL, "trace not allocated for posterior probabilities");

  tr->st[tr->N] = st;
  tr->pp[tr->N] = postp;
  tr->N++;
  return eslOK;

 ERROR:
  return status;
}

int
p7_trace_Reverse(P7_TRACE *tr)
{
  int i;

  esl_vec_IReverse(tr->st, tr->st, tr->N);
  if (tr->pp != NULL)
    esl_vec_FReverse(tr->pp, tr->pp, tr->N);

  for (i = 0; i < tr->N; i++)
    {
      switch (tr->st[i]) {
      case p7_ML: tr->st[i] = p7_MR; break;
      case p7_IL: tr->st[i] = p7_IR; break;
      case p7_DL: tr->st[i] = p7_DR; break;
      case p7_MR: tr->st[i] = p7_ML; break;
      case p7_IR: tr->st[i] = p7_IL; break;
      case p7_DR: tr->st[i] = p7_DL; break;
      default: break;
      }
    }
  return eslOK;
}


int
p7_trace_Reuse(P7_TRACE *tr)
{
  tr->N         = 0;
  tr->ndom      = 0;
  tr->M         = 0;
  tr->L         = 0;
  tr->is_multihit = TRUE;
  tr->parent    = NULL;
  return eslOK;
}


void
p7_trace_Destroy(P7_TRACE *tr)
{
  if (tr == NULL) return;
  if (tr->st  != NULL) free(tr->st);
  if (tr->pp  != NULL) free(tr->pp);
  if (tr->dom != NULL) free(tr->dom);
  free(tr);
  return;
}

int
p7_trace_Score(P7_TRACE *tr, const ESL_DSQ *dsq, const P7_PROFILE *gm, float *ret_sc)
{
  float sc = 0.0f;
  int   i, k, s, s_prev;

  if (tr->N < 2) { *ret_sc = 0.0f; return eslOK; }

  i = 0;
  k = 0;

  for (int z = 0; z < tr->N; z++)
    {
      s = tr->st[z];
      s_prev = (z == 0) ? -1 : tr->st[z-1];

      switch(s) {
      case p7_ML:
      case p7_MR:
      case p7_MG:
	sc += gm->rsc[dsq[i]][k*2];
	break;
      case p7_IL:
      case p7_IR:
      case p7_IG:
	sc += gm->rsc[dsq[i]][k*2+1];
	break;
      }

      if (z > 0) {
	switch (s_prev) {
	case p7_S:
	  if (s == p7_N) sc += gm->xsc[p7_S][p7_S_N];
	  else           return eslFAIL;
	  break;

	case p7_N:
	  if      (s == p7_N) sc += gm->xsc[p7_N][p7_N_N];
	  else if (s == p7_B) sc += gm->xsc[p7_N][p7_N_B];
	  else                return eslFAIL;
	  break;

	case p7_B:
	  if      (s == p7_ML) sc += p7P_TSC(gm, 0, p7P_B_ML);
	  else if (s == p7_MG) sc += p7P_TSC(gm, 0, p7P_B_MG);
	  else                 return eslFAIL;
	  break;

	case p7_ML:
	  if      (s == p7_ML) sc += p7P_TSC(gm, k, p7P_ML_ML);
	  else if (s == p7_IL) sc += p7P_TSC(gm, k, p7P_ML_IL);
	  else if (s == p7_DL) sc += p7P_TSC(gm, k, p7P_ML_DL);
	  else if (s == p7_E)  sc += gm->xsc[p7_E][p7_E_L];
	  else                 return eslFAIL;
	  break;
	case p7_MR:
	  if      (s == p7_MR) sc += p7P_TSC(gm, k, p7P_MR_MR);
	  else if (s == p7_IR) sc += p7P_TSC(gm, k, p7P_MR_IR);
	  else if (s == p7_DR) sc += p7P_TSC(gm, k, p7P_MR_DR);
	  else if (s == p7_E)  sc += gm->xsc[p7_E][p7_E_R];
	  else                 return eslFAIL;
	  break;
	case p7_MG:
	  if      (s == p7_MG) sc += p7P_TSC(gm, k, p7P_MG_MG);
	  else if (s == p7_IG) sc += p7P_TSC(gm, k, p7P_MG_IG);
	  else if (s == p7_DG) sc += p7P_TSC(gm, k, p7P_MG_DG);
	  else if (s == p7_E)  sc += gm->xsc[p7_E][p7_E_G];
	  else                 return eslFAIL;
	  break;

	case p7_IL:
	  if      (s == p7_ML) sc += p7P_TSC(gm, k, p7P_IL_ML);
	  else if (s == p7_IL) sc += p7P_TSC(gm, k, p7P_IL_IL);
	  else                 return eslFAIL;
	  break;
	case p7_IR:
	  if      (s == p7_MR) sc += p7P_TSC(gm, k, p7P_IR_MR);
	  else if (s == p7_IR) sc += p7P_TSC(gm, k, p7P_IR_IR);
	  else                 return eslFAIL;
	  break;
	case p7_IG:
	  if      (s == p7_MG) sc += p7P_TSC(gm, k, p7P_IG_MG);
	  else if (s == p7_IG) sc += p7P_TSC(gm, k, p7P_IG_IG);
	  else                 return eslFAIL;
	  break;

	case p7_DL:
	  if      (s == p7_ML) sc += p7P_TSC(gm, k, p7P_DL_ML);
	  else if (s == p7_DL) sc += p7P_TSC(gm, k, p7P_DL_DL);
	  else                 return eslFAIL;
	  break;
	case p7_DR:
	  if      (s == p7_MR) sc += p7P_TSC(gm, k, p7P_DR_MR);
	  else if (s == p7_DR) sc += p7P_TSC(gm, k, p7P_DR_DR);
	  else                 return eslFAIL;
	  break;
	case p7_DG:
	  if      (s == p7_MG) sc += p7P_TSC(gm, k, p7P_DG_MG);
	  else if (s == p7_DG) sc += p7P_TSC(gm, k, p7P_DG_DG);
	  else                 return eslFAIL;
	  break;

	case p7_E:
	  if      (s == p7_C) sc += gm->xsc[p7_E][p7_E_C];
	  else if (s == p7_J) sc += gm->xsc[p7_E][p7_E_J];
	  else                return eslFAIL;
	  break;

	case p7_C:
	  if      (s == p7_C) sc += gm->xsc[p7_C][p7_C_C];
	  else if (s == p7_T) sc += gm->xsc[p7_C][p7_C_T];
	  else                return eslFAIL;
	  break;

	case p7_J:
	  if      (s == p7_J) sc += gm->xsc[p7_J][p7_J_J];
	  else if (s == p7_B) sc += gm->xsc[p7_J][p7_J_B];
	  else                return eslFAIL;
	  break;

	case p7_T:
	  return eslFAIL;

	default: return eslFAIL;
	}
      }

      switch (s) {
      case p7_ML: case p7_MR: case p7_MG: i++; k++; break;
      case p7_IL: case p7_IR: case p7_IG: i++; break;
      case p7_DL: case p7_DR: case p7_DG: k++; break;
      case p7_N: case p7_C: case p7_J: i++; break;
      case p7_S: k = 0; i = 0; break;
      default: break;
      }
    }
  *ret_sc = sc;
  return eslOK;
}


int
p7_trace_Validate(const P7_TRACE *tr, const ESL_ALPHABET *abc, const ESL_DSQ *dsq, char *errbuf)
{
  int   curr_st, prev_st;
  int   z;
  int   i, k;

  if (tr->N == 0) return eslOK;

  i = k = 0;

  if (tr->st[0] != p7_S) ESL_FAIL(eslFAIL, errbuf, "Trace doesn't start in S state.");
  if (tr->st[tr->N-1] != p7_T) ESL_FAIL(eslFAIL, errbuf, "Trace doesn't end in T state.");

  for (z = 1; z < tr->N; z++)
    {
      curr_st = tr->st[z];
      prev_st = tr->st[z-1];

      switch(curr_st) {
      case p7_ML: case p7_MR: case p7_MG: k++; i++; break;
      case p7_IL: case p7_IR: case p7_IG:      i++; break;
      case p7_DL: case p7_DR: case p7_DG: k++;      break;
      case p7_S:  k = 0;   i = 0;   break;
      case p7_N:  case p7_J: case p7_C:      i++; break;
      case p7_E:  case p7_B: case p7_T:             break;
      default: ESL_FAIL(eslFAIL, errbuf, "Trace contains invalid state type %d.", curr_st);
      }

      if (k > tr->M && tr->M > 0)
	ESL_FAIL(eslFAIL, errbuf, "Trace passes beyond model length M=%d", tr->M);

      if (dsq != NULL && (curr_st == p7_ML || curr_st == p7_MG || curr_st == p7_MR ||
			  curr_st == p7_IL || curr_st == p7_IG || curr_st == p7_IR ||
			  curr_st == p7_N || curr_st == p7_C || curr_st == p7_J))
	if (! esl_abc_IsResidue(abc, dsq[i]))
	  ESL_FAIL(eslFAIL, errbuf, "Trace contains emission of invalid residue at position %d", i);

      switch (prev_st) {
      case p7_S:
	if (curr_st != p7_N) ESL_FAIL(eslFAIL, errbuf, "S->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_N:
	if (curr_st != p7_N && curr_st != p7_B) ESL_FAIL(eslFAIL, errbuf, "N->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_B:
	if (curr_st != p7_ML && curr_st != p7_MG) ESL_FAIL(eslFAIL, errbuf, "B->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_ML:
	if (curr_st != p7_ML && curr_st != p7_IL && curr_st != p7_DL && curr_st != p7_E) ESL_FAIL(eslFAIL, errbuf, "ML->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_MR:
	if (curr_st != p7_MR && curr_st != p7_IR && curr_st != p7_DR && curr_st != p7_E) ESL_FAIL(eslFAIL, errbuf, "MR->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_MG:
	if (curr_st != p7_MG && curr_st != p7_IG && curr_st != p7_DG && curr_st != p7_E) ESL_FAIL(eslFAIL, errbuf, "MG->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_IL:
	if (curr_st != p7_ML && curr_st != p7_IL) ESL_FAIL(eslFAIL, errbuf, "IL->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_IR:
	if (curr_st != p7_MR && curr_st != p7_IR) ESL_FAIL(eslFAIL, errbuf, "IR->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_IG:
	if (curr_st != p7_MG && curr_st != p7_IG) ESL_FAIL(eslFAIL, errbuf, "IG->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_DL:
	if (curr_st != p7_ML && curr_st != p7_DL) ESL_FAIL(eslFAIL, errbuf, "DL->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_DR:
	if (curr_st != p7_MR && curr_st != p7_DR) ESL_FAIL(eslFAIL, errbuf, "DR->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_DG:
	if (curr_st != p7_MG && curr_st != p7_DG) ESL_FAIL(eslFAIL, errbuf, "DG->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_E:
	if (curr_st != p7_C && curr_st != p7_J) ESL_FAIL(eslFAIL, errbuf, "E->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_C:
	if (curr_st != p7_C && curr_st != p7_T) ESL_FAIL(eslFAIL, errbuf, "C->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_J:
	if (curr_st != p7_J && curr_st != p7_B) ESL_FAIL(eslFAIL, errbuf, "J->%s invalid", p7_hmm_DecodeStatetype(curr_st));
	break;
      case p7_T:
	ESL_FAIL(eslFAIL, errbuf, "T state is not a predecessor");
	break;
      default:
	ESL_FAIL(eslFAIL, errbuf, "trace contains invalid state %d", prev_st);
      }
    }
  return eslOK;
}


int
p7_trace_Compare(const P7_TRACE *tr1, const P7_TRACE *tr2, float pptol)
{
  int z;

  if (tr1->N != tr2->N) return eslFAIL;
  if (tr1->M != tr2->M) return eslFAIL;
  if (tr1->L != tr2->L) return eslFAIL;

  for (z = 0; z < tr1->N; z++) {
    if (tr1->st[z] != tr2->st[z]) return eslFAIL;
    if (tr1->k[z] != tr2->k[z]) return eslFAIL;
    if (tr1->i[z] != tr2->i[z]) return eslFAIL;
  }

  if (tr1->pp != NULL && tr2->pp != NULL) {
    for (z = 0; z < tr1->N; z++)
      if (esl_FCompare(tr1->pp[z], tr2->pp[z], pptol) != eslOK)
	return eslFAIL;
  }
  else if (tr1->pp != NULL || tr2->pp != NULL) return eslFAIL;


  if (tr1->ndom != tr2->ndom) return eslFAIL;
  for (z = 0; z < tr1->ndom; z++) {
    if (tr1->dom[z].ia != tr2->dom[z].ia) return eslFAIL;
    if (tr1->dom[z].ib != tr2->dom[z].ib) return eslFAIL;
    if (tr1->dom[z].ka != tr2->dom[z].ka) return eslFAIL;
    if (tr1->dom[z].kb != tr2->dom[z].kb) return eslFAIL;
  }
  return eslOK;
}


float
p7_trace_GetExpectedAccuracy(const P7_TRACE *tr)
{
  float acc = 0.0;
  int z;

  if (tr->pp == NULL) return 0.0;
  for (z = 0; z < tr->N; z++)
    {
      if (tr->st[z] == p7_ML || tr->st[z] == p7_MG || tr->st[z] == p7_MR ||
          tr->st[z] == p7_IL || tr->st[z] == p7_IG || tr->st[z] == p7_IR ||
          tr->st[z] == p7_N  || tr->st[z] == p7_C  || tr->st[z] == p7_J)
	acc += tr->pp[z];
    }
  return acc;
}

int
p7_trace_SetPP(P7_TRACE *tr, const P7_GMX *pp)
{
  int   status;
  int   q,r,pos;
  int   z, i, k, s_curr, s_prev;
  float pp_val;

  if (tr->pp == NULL) {
    ESL_ALLOC(tr->pp, sizeof(float) * tr->nalloc);
  }

  i = k = 0;
  for (z = 0; z < tr->N; z++)
    {
      s_curr = tr->st[z];
      s_prev = (z==0) ? -1 : tr->st[z-1];

      pp_val = 0.0;
      switch (s_curr) {
      case p7_ML:
      case p7_MG:
      case p7_MR:
	pp_val = p7G_MMX(pp, i, k);
	i++; k++;
	break;

      case p7_IL:
      case p7_IG:
      case p7_IR:
	pp_val = p7G_IMX(pp, i, k);
	i++;
	break;

      case p7_DL:
      case p7_DG:
      case p7_DR:
	pp_val = p7G_DMX(pp, i, k);
	k++;
	break;

      case p7_N:
	if (s_curr == s_prev) pp_val = P7G_NX(pp, i, p7G_N_N);
	else                  pp_val = P7G_NX(pp, i, p7G_S_N);
	i++;
	break;

      case p7_C:
	if (s_curr == s_prev) pp_val = P7G_NX(pp, i, p7G_C_C);
	else                  pp_val = P7G_NX(pp, i, p7G_E_C);
	i++;
	break;

      case p7_J:
	if (s_curr == s_prev) pp_val = P7G_NX(pp, i, p7G_J_J);
	else                  pp_val = P7G_NX(pp, i, p7G_E_J);
	i++;
	break;

      case p7_B:
	if (s_prev == p7_N) pp_val = P7G_NX(pp, i, p7G_N_B);
	else                pp_val = P7G_NX(pp, i, p7G_J_B);
	break;

      case p7_E:
	pp_val = P7G_NX(pp, i, p7G_E_L);
	break;

      case p7_S:
      case p7_T:
	pp_val = 1.0;
	break;
      }
      tr->pp[z] = pp_val;
    }
  return eslOK;

 ERROR:
  return status;
}

int
p7_trace_Dump(FILE *fp, const P7_TRACE *tr, const P7_PROFILE *gm, const ESL_DSQ *dsq)
{
  int z;
  int i,k;

  fprintf(fp, "Trace (length %d):\n", tr->N);
  fprintf(fp, "idx st   k     i   res emitted? postp\n");
  fprintf(fp, "--- -- ----- ----- --- -------- ------\n");

  i = k = 0;
  for (z = 0; z < tr->N; z++)
    {
      fprintf(fp, "%3d %-2s ", z, p7_hmm_DecodeStatetype(tr->st[z]));
      fprintf(fp, "%5d ", k);
      fprintf(fp, "%5d ", i);

      switch (tr->st[z]) {
      case p7_ML:
      case p7_MR:
      case p7_MG:
	fprintf(fp, " %c ",   gm->abc->sym[dsq[i+1]]);
	fprintf(fp, "%8s ", "yes");
	break;
      case p7_IL:
      case p7_IR:
      case p7_IG:
	fprintf(fp, " %c ",   gm->abc->sym[dsq[i+1]]);
	fprintf(fp, "%8s ", "yes");
	break;
      case p7_N:
      case p7_J:
      case p7_C:
	fprintf(fp, " %c ",   gm->abc->sym[dsq[i+1]]);
	fprintf(fp, "%8s ", "yes");
	break;
      default:
	fprintf(fp, "   %8s ", "no");
	break;
      }

      if (tr->pp != NULL) fprintf(fp, "%6.4f\n", tr->pp[z]);
      else                fprintf(fp, "    -\n");

      switch (tr->st[z]) {
      case p7_ML: case p7_MR: case p7_MG: i++; k++; break;
      case p7_IL: case p7_IR: case p7_IG: i++; break;
      case p7_DL: case p7_DR: case p7_DG: k++; break;
      case p7_N: case p7_C: case p7_J:   i++; break;
      default: break;
      }
    }
  return eslOK;
}

int
p7_trace_DumpDomains(FILE *fp, P7_TRACE *tr, P7_PROFILE *gm)
{
  int d;

  fprintf(fp, "Domain table (from trace):\n");
  fprintf(fp, " dom     i-start i-end   k-start k-end\n");
  fprintf(fp, " ---     ------- -----   ------- -----\n");
  for (d = 0; d < tr->ndom; d++)
    {
      fprintf(fp, " %3d EST %7d %5d   %7d %5d\n", d+1, tr->dom[d].ia, tr->dom[d].ib, tr->dom[d].ka, tr->dom[d].kb);
    }
  return eslOK;
}
