  return forward_engine(FALSE, dsq, L, om, ox, opt_sc);
}

int
p7_Backward(const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, const P7_OMX *fwd, P7_OMX *bck, float *opt_sc)
{
  return backward_engine(TRUE, dsq, L, om, fwd, bck, opt_sc);
}

int
p7_BackwardParser(const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, const P7_OMX *fwd, P7_OMX *bck, float *opt_sc)
{
  return backward_engine(FALSE, dsq, L, om, fwd, bck, opt_sc);
}

static int
forward_engine(int do_full, const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, P7_OMX *ox, float *opt_sc)
{
  register float32x4_t mpv, dpv, ipv;
  register float32x4_t sv;
  register float32x4_t dcv;
  register float32x4_t xEv;
  register float32x4_t xBv;
  register float32x4_t zerov;
  float xN, xE, xB, xC, xJ;
  int i;
  int q;
  int j;
  int Q = p7O_NQ_F(om->M);
  float32x4_t *dpc = ox->dpf[0];
  float32x4_t *dpp;
  float32x4_t *rp;
  float32x4_t *tp;

  zerov   = vmovq_n_f32(0.0f);
  ox->M = om->M;
  ox->L = L;
  ox->has_own_scales = TRUE;

  for (q = 0; q < Q; q++) {
    MMO(dpc,q) = IMOs(dpc,q) = DMO(dpc,q) = zerov;
  }
  xE = ox->xmx[p7X_E] = 0.;
  xN = ox->xmx[p7X_N] = 1.;
  xJ = ox->xmx[p7X_J] = 0.;
  xB = ox->xmx[p7X_B] = om->xf[p7O_N][p7O_MOVE];
  xC = ox->xmx[p7X_C] = 0.;
  ox->xmx[p7X_SCALE]  = 1.0;
  ox->totscale        = 0.0;

  for (i = 1; i <= L; i++)
    {
      dpp = dpc;
      dpc = ox->dpf[do_full * i];

      rp  = om->rfv[dsq[i]];
      tp  = om->tfv;

      dcv = vmovq_n_f32(0.0f);
      xEv = vmovq_n_f32(0.0f);
      xBv = vmovq_n_f32(xB);


      mpv = vextq_f32(zerov, MMO(dpp,Q-1), 3);
      dpv = vextq_f32(zerov, DMO(dpp,Q-1), 3);
      ipv = vextq_f32(zerov, IMO(dpp,Q-1), 3);

      for (q = 0; q < Q; q++)
      {
        sv = vmulq_f32(xBv, *tp); tp++;
        sv = vaddq_f32(sv, vmulq_f32(mpv, *tp)); tp++;
        sv = vaddq_f32(sv, vmulq_f32(ipv, *tp)); tp++;
        sv = vaddq_f32(sv, vmulq_f32(dpv, *tp)); tp++;

        sv = vmulq_f32(sv, *rp); rp++;
        xEv = vaddq_f32(xEv, sv);

        mpv = MMO(dpp,q);
        dpv = DMO(dpp,q);
        ipv = IMO(dpp,q);

        MMO(dpc,q) = sv;
        DMO(dpc,q) = dcv;

        dcv = vmulq_f32(sv, *tp); tp++;

        sv = vmulq_f32(mpv, *tp); tp++;
        IMO(dpc,q) = vaddq_f32(sv, vmulq_f32(ipv, *tp)); tp++;
      }

      dcv = vextq_f32(zerov, dcv, 3);
      DMO(dpc,0) = vmovq_n_f32(0.0);
      tp = &(om->tfv[7*Q]);
      for (q = 0; q < Q; q++) {
        DMO(dpc,q) = vaddq_f32(dcv, DMO(dpc,q));
        dcv = vmulq_f32(DMO(dpc,q), *tp); tp++;
      }

      if (om->M > 100)
      {
        for (j = 1; j < 4; j++)
        {
          register uint32x4_t cv;
          dcv = vextq_f32(zerov, dcv, 3);
          tp = &(om->tfv[7*Q]);
          cv = vmovq_n_u32(0);
          for (q = 0; q < Q; q++)
          {
            sv = vaddq_f32(dcv, DMO(dpc,q));
            cv = vorrq_u32(cv, vcgtq_f32(sv, DMO(dpc,q)));
            DMO(dpc,q) = sv;
            dcv = vmulq_f32(dcv, *tp); tp++;
          }
          if (esl_neon_hmax_u32(cv) == 0) break;
        }
      }
      else
      {
        for (j = 1; j < 4; j++) {
          dcv = vextq_f32(zerov, dcv, 3);
          tp = &(om->tfv[7*Q]);
          for (q = 0; q < Q; q++) {
            DMO(dpc,q) = vaddq_f32(dcv, DMO(dpc,q));
            dcv = vmulq_f32(dcv, *tp); tp++;
          }
        }
      }

      for (q = 0; q < Q; q++) xEv = vaddq_f32(DMO(dpc,q), xEv);

      esl_neon_hsum_f32(xEv, &xE);

      xN = xN * om->xf[p7O_N][p7O_LOOP];
      xC = xC * om->xf[p7O_C][p7O_LOOP] + xE * om->xf[p7O_E][p7O_MOVE];
      xJ = xJ * om->xf[p7O_J][p7O_LOOP] + xE * om->xf[p7O_E][p7O_LOOP];
      xB = xJ * om->xf[p7O_J][p7O_MOVE] + xN * om->xf[p7O_N][p7O_MOVE];


      if (xE > 1.0e4) {
        xN /= xE;
        xC /= xE;
        xJ /= xE;
        xB /= xE;
        xEv = vmovq_n_f32(1.0f/xE);
        for (q = 0; q < Q; q++) {
          MMO(dpc,q) = vmulq_f32(MMO(dpc,q), xEv);
          DMO(dpc,q) = vmulq_f32(DMO(dpc,q), xEv);
          IMO(dpc,q) = vmulq_f32(IMO(dpc,q), xEv);
        }
        ox->xmx[i*p7X_NXCELLS+p7X_SCALE] = xE;
        ox->totscale += log(xE);
        xE = 1.0;
      } else {
        ox->xmx[i*p7X_NXCELLS+p7X_SCALE] = 1.0;
      }

      ox->xmx[i*p7X_NXCELLS+p7X_E] = xE;
      ox->xmx[i*p7X_NXCELLS+p7X_N] = xN;
      ox->xmx[i*p7X_NXCELLS+p7X_J] = xJ;
      ox->xmx[i*p7X_NXCELLS+p7X_B] = xB;
      ox->xmx[i*p7X_NXCELLS+p7X_C] = xC;
    }

  if      (isnan(xC))                                      return eslERANGE;
  else if (L > 0 && xC == 0.0)                             return eslERANGE;
  else if (isinf(xC) && xC > 0)                            return eslERANGE;
  if (opt_sc != NULL) *opt_sc = ox->totscale + log(xC * om->xf[p7O_C][p7O_MOVE]);
  return eslOK;
}

static int
backward_engine(int do_full, const ESL_DSQ *dsq, int L, const P7_OPROFILE *om, const P7_OMX *fwd, P7_OMX *bck, float *opt_sc)
{
  register float32x4_t mpv, ipv, dpv;
  register float32x4_t mcv, dcv;
  register float32x4_t tmmv, timv, tdmv;
  register float32x4_t xBv;
  register float32x4_t xEv;
  register float32x4_t zerov;
  float xN, xE, xB, xC, xJ;
  int i;
  int q;
  int j;
  int Q = p7O_NQ_F(om->M);
  float32x4_t *dpc;
  float32x4_t *dpp;
  float32x4_t *rp;
  float32x4_t *tp;

  zerov = vmovq_n_f32(0.0f);

  bck->M = om->M;
  bck->L = L;
  bck->has_own_scales = FALSE;
  dpc = bck->dpf[do_full * L];
  xJ = 0.0;
  xB = 0.0;
  xN = 0.0;
  xC = om->xf[p7O_C][p7O_MOVE];
  xE = xC * om->xf[p7O_E][p7O_MOVE];
  xEv = vmovq_n_f32(xE);
  dcv = vmovq_n_f32(0.0);
  for (q = 0; q < Q; q++) {
    MMO(dpc,q) = DMO(dpc,q) = xEv;
  }
  for (q = 0; q < Q; q++) {
    IMO(dpc,q) = zerov;
  }
  tp = &(om->tfv[8*Q - 1]);
  dpv = vextq_f32(DMO(dpc,Q-1), zerov, 1);
  for (q = Q-1; q >= 0; q--)
  {
    dcv = vmulq_f32(dpv, *tp); tp--;
    DMO(dpc,q) = vaddq_f32(DMO(dpc,q), dcv);
    dpv = DMO(dpc,q);
  }

  for (j=1; j<4; j++)
  {
    tp = &(om->tfv[8*Q - 1]);
    dcv = vextq_f32(dcv, zerov, 1);
    for (q = Q-1; q >= 0; q--)
    {
      dcv = vmulq_f32(dcv, *tp); tp--;
      DMO(dpc,q) = vaddq_f32(DMO(dpc,q), dcv);
    }
  }

  tp = &(om->tfv[7*Q - 3]);
  dcv = vextq_f32(DMO(dpc,0), zerov, 1);
  for (q = Q-1; q >= 0; q--)
  {
    MMO(dpc,q) = vaddq_f32(MMO(dpc,q), vmulq_f32(dcv, *tp)); tp -= 7;
    dcv = DMO(dpc,q);
  }
  if (fwd->xmx[L*p7X_NXCELLS+p7X_SCALE] != 1.0) {
    xE *= fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
    xN *= fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
    xC *= fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
    xJ *= fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
    xB *= fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
    xEv = vmovq_n_f32(1.0 / fwd->xmx[L*p7X_NXCELLS+p7X_SCALE]);
    for (q = 0; q < Q; q++) {
      MMO(dpc,q) = vmulq_f32(MMO(dpc,q), xEv);
      DMO(dpc,q) = vmulq_f32(DMO(dpc,q), xEv);
      IMO(dpc,q) = vmulq_f32(IMO(dpc,q), xEv);
    }
  }
  bck->xmx[L*p7X_NXCELLS+p7X_SCALE] = fwd->xmx[L*p7X_NXCELLS+p7X_SCALE];
  bck->totscale += log(bck->xmx[L*p7X_NXCELLS+p7X_SCALE]);

  bck->xmx[L*p7X_NXCELLS+p7X_E] = xE;
  bck->xmx[L*p7X_NXCELLS+p7X_N] = xN;
  bck->xmx[L*p7X_NXCELLS+p7X_J] = xJ;
  bck->xmx[L*p7X_NXCELLS+p7X_B] = xB;
  bck->xmx[L*p7X_NXCELLS+p7X_C] = xC;


  for (i = L-1; i >= 1; i--)
    {
      dpc = bck->dpf[do_full * i];
      dpp = bck->dpf[do_full * (i+1)];

      rp  = &(om->rfv[dsq[i+1]][Q-1]);
      tp  = &(om->tfv[7*Q - 1]);

      tmmv = vextq_f32(om->tfv[1],   zerov, 1);
      timv = vextq_f32(om->tfv[2],   zerov, 1);
      tdmv = vextq_f32(om->tfv[3],   zerov, 1);
      mpv  = vmulq_f32(MMO(dpp,0), om->rfv[dsq[i+1]][0]);
      mpv  = vextq_f32(mpv, zerov, 1);

      xBv = vmovq_n_f32(0.0f);
      for (q = Q-1; q >= 0; q--)
      {
        ipv = IMO(dpp, q);
        IMO(dpc,q) = vaddq_f32(vmulq_f32(ipv, *tp), vmulq_f32(mpv, timv)); tp--;
        DMO(dpc,q) = vmulq_f32(mpv, tdmv);
        mcv = vaddq_f32(vmulq_f32(ipv, *tp), vmulq_f32(mpv, tmmv)); tp-=2;

        mpv = vmulq_f32(MMO(dpp,q), *rp); rp--;

        MMO(dpc,q) = mcv;
        tdmv = *tp; tp--;
        timv = *tp; tp--;
        tmmv = *tp; tp--;

        xBv = vaddq_f32(xBv, vmulq_f32(mpv, *tp)); tp--;
      }

      esl_neon_hsum_f32(xBv, &xB);
      xBv = vmovq_n_f32(xB);

      xC = xC * om->xf[p7O_C][p7O_LOOP];
      xJ = xB * om->xf[p7O_J][p7O_MOVE] + xJ * om->xf[p7O_J][p7O_LOOP];
      xN = xB * om->xf[p7O_N][p7O_MOVE] + xN * om->xf[p7O_N][p7O_LOOP];
      xE = xC * om->xf[p7O_E][p7O_MOVE] + xJ * om->xf[p7O_E][p7O_LOOP];
      xEv = vmovq_n_f32(xE);

      tp = &(om->tfv[8*Q - 1]);
      dpv = vaddq_f32(DMO(dpc,0), xEv);
      dpv = vextq_f32(dpv, zerov, 1);

      for (q = Q-1; q >= 0; q--)
      {
        dcv = vmulq_f32(dpv, *tp); tp--;
        DMO(dpc,q) = vaddq_f32(DMO(dpc,q), vaddq_f32(dcv, xEv));
        dpv = DMO(dpc,q);
        MMO(dpc,q) = vaddq_f32(MMO(dpc,q), xEv);
      }

      for (j=1; j<4; j++) {
        dcv = vextq_f32(dcv, zerov, 1);
        tp = &(om->tfv[8*Q - 1]);
        for (q = Q-1; q >=0; q--)
        {
          dcv = vmulq_f32(dcv, *tp); tp--;
          DMO(dpc,q) = vaddq_f32(DMO(dpc,q), dcv);
        }
      }
      dcv = vextq_f32(DMO(dpc,0), zerov, 1);
      tp = &(om->tfv[7*Q-3]);
      for (q = Q-1; q >=0; q--)
      {
        MMO(dpc,q) = vaddq_f32(MMO(dpc,q), vmulq_f32(dcv, *tp)); tp-=7;
        dcv = DMO(dpc,q);
      }

      if (xB > 1.0e16) bck->has_own_scales = TRUE;
      if (bck->has_own_scales) bck->xmx[i*p7X_NXCELLS+p7X_SCALE] = (xB > 1.0e4 ? xB : 1.0);
      else                     bck->xmx[i*p7X_NXCELLS+p7X_SCALE] = fwd->xmx[i*p7X_NXCELLS+p7X_SCALE];

      if (bck->xmx[i*p7X_NXCELLS+p7X_SCALE] != 1.0)
      {
        xE /= bck->xmx[i*p7X_NXCELLS+p7X_SCALE];
        xN /= bck->xmx[i*p7X_NXCELLS+p7X_SCALE];
        xJ /= bck->xmx[i*p7X_NXCELLS+p7X_SCALE];
        xB /= bck->xmx[i*p7X_NXCELLS+p7X_SCALE];
        xC /= bck->xmx[i*p7X_NXCELLS+p7X_SCALE];
        xBv = vmovq_n_f32(1.0f / bck->xmx[i*p7X_NXCELLS+p7X_SCALE]);
        for (q = 0; q < Q; q++) {
          MMO(dpc,q) = vmulq_f32(MMO(dpc,q), xBv);
          DMO(dpc,q) = vmulq_f32(DMO(dpc,q), xBv);
          IMO(dpc,q) = vmulq_f32(IMO(dpc,q), xBv);
        }
      }
      bck->totscale += log(bck->xmx[i*p7X_NXCELLS+p7X_SCALE]);

      bck->xmx[i*p7X_NXCELLS+p7X_E] = xE;
      bck->xmx[i*p7X_NXCELLS+p7X_N] = xN;
      bck->xmx[i*p7X_NXCELLS+p7X_J] = xJ;
      bck->xmx[i*p7X_NXCELLS+p7X_B] = xB;
      bck->xmx[i*p7X_NXCELLS+p7X_C] = xC;
    }

  dpp = bck->dpf[do_full * 1];
  tp = om->tfv;
  rp = om->rfv[dsq[1]];
  xBv = vmovq_n_f32(0.0f);
  for (q = 0; q < Q; q++)
  {
      mpv = vmulq_f32(MMO(dpp,q), *rp); rp++;
      mpv = vmulq_f32(mpv, *tp); tp+=7;
      xBv = vaddq_f32(xBv, mpv);
  }

  esl_neon_hsum_f32(xBv, &xB);
  xN = xB * om->xf[p7O_N][p7O_MOVE] + xN * om->xf[p7O_N][p7O_LOOP];
  bck->xmx[p7X_B] = xB;
  bck->xmx[p7X_C] = 0.0;
  bck->xmx[p7X_J] = 0.0;
  bck->xmx[p7X_N] = xN;
  bck->xmx[p7X_E] = 0.0;
  bck->xmx[p7X_SCALE] = 1.0;

  if      (isnan(xN))                                      return eslERANGE;
  else if (L > 0 && xN == 0.0)                             return eslERANGE;
  else if (isinf(xN) && xN > 0)                            return eslERANGE;
  if (opt_sc != NULL) *opt_sc = bck->totscale + log(xN);
  return eslOK;
}
