P7_OMX *
p7_omx_Create(int alloc_M, int alloc_L, int alloc_XL)
{
  P7_OMX *ox = NULL;
  int i;
  int status;

  ESL_ALLOC(ox, sizeof(P7_OMX));
  ox->dpmem = NULL;
  ox->dpb = NULL;
  ox->dpw = NULL;
  ox->dpf = NULL;
  ox->xmx = NULL;
  ox->xmem = NULL;

  ox->alloc_R     = alloc_L+1;
  ox->valid_R     = ox->alloc_R;
  ox->alloc_Q4    = p7O_NQ_F(alloc_M);
  ox->alloc_Q8    = p7O_NQ_W(alloc_M);
  ox->alloc_Q16   = p7O_NQ_B(alloc_M);
  ox->ncells = (int64_t)ox->alloc_R * (int64_t)ox->alloc_Q4 * 4;

  ESL_ALLOC(ox->dpmem, sizeof(uint8x16_t) * ((int64_t)ox->alloc_R * (int64_t)ox->alloc_Q4 * p7X_NSCELLS + 15) );

  ESL_ALLOC(ox->dpb, sizeof(uint8x16_t *) * ox->alloc_R);
  ESL_ALLOC(ox->dpw, sizeof(int16x8_t *)  * ox->alloc_R);
  ESL_ALLOC(ox->dpf, sizeof(float32x4_t *)* ox->alloc_R);

  ox->dpb[0] = (uint8x16_t *) (((unsigned long int)((char *)ox->dpmem + 15)) & (~0xfUL));
  ox->dpw[0] = (int16x8_t *)  (((unsigned long int)((char *)ox->dpmem + 15)) & (~0xfUL));
  ox->dpf[0] = (float32x4_t *)(((unsigned long int)((char *)ox->dpmem + 15)) & (~0xfUL));

  for (i = 1; i <= alloc_L; i++) {
    ox->dpf[i] = ox->dpf[0] + (int64_t)i * (int64_t)ox->alloc_Q4 * p7X_NSCELLS;
    ox->dpw[i] = ox->dpw[0] + (int64_t)i * (int64_t)ox->alloc_Q8 * p7X_NSCELLS;
    ox->dpb[i] = ox->dpb[0] + (int64_t)i * (int64_t)ox->alloc_Q16;
  }

  ox->alloc_XR = alloc_XL+1;
  ESL_ALLOC(ox->xmem, sizeof(float) * (ox->alloc_XR * p7X_NXCELLS + 15));
  ox->xmx = (float *) (((unsigned long int)((char *)ox->xmem + 15)) & (~0xfUL));

  ox->M           = 0;
  ox->L           = 0;
  ox->totscale    = 0.0;
  ox->has_own_scales = TRUE;

  return ox;

 ERROR:
  p7_omx_Destroy(ox);
  return NULL;
}


int
p7_omx_GrowTo(P7_OMX *ox, int alloc_M, int alloc_L, int alloc_XL)
{
  void *p;
  int nq_f = p7O_NQ_F(alloc_M);
  int nq_w = p7O_NQ_W(alloc_M);
  int nq_b = p7O_NQ_B(alloc_M);
  int64_t ncells = (int64_t)(alloc_L+1) * (int64_t)nq_f * 4;
  int reset_row_pointers = FALSE;
  int i;
  int status;


  if (ox->alloc_Q4*4 >= alloc_M && ox->valid_R >= alloc_L && ox->alloc_XR >= alloc_XL+1) return eslOK;

  if (ncells > ox->ncells)
  {
      ESL_RALLOC(ox->dpmem, p, sizeof(uint8x16_t) * ((int64_t)(alloc_L+1) * (int64_t)nq_f * p7X_NSCELLS + 15));
      ox->ncells = ncells;
      reset_row_pointers = TRUE;
  }

  if (alloc_XL+1 > ox->alloc_XR)
  {
      ESL_RALLOC(ox->xmem, p, sizeof(float) * ((alloc_XL+1) * p7X_NXCELLS + 15));
      ox->alloc_XR = alloc_XL+1;
      ox->xmx = (float *) (((unsigned long int)((char *)ox->xmem + 15)) & (~0xfUL));
  }

  if (alloc_L > ox->alloc_R) {
    ESL_RALLOC(ox->dpb, p, sizeof(uint8x16_t *) * (alloc_L+1));
    ESL_RALLOC(ox->dpw, p, sizeof(int16x8_t *)  * (alloc_L+1));
    ESL_RALLOC(ox->dpf, p, sizeof(float32x4_t *)* (alloc_L+1));
    ox->alloc_R = alloc_L+1;
    reset_row_pointers = TRUE;
  }
  if (alloc_M > ox->alloc_Q4*4) reset_row_pointers = TRUE;
  if (alloc_L > ox->valid_R)    reset_row_pointers = TRUE;

  if (reset_row_pointers)
    {
      ox->dpb[0] = (uint8x16_t *) (((unsigned long int)((char *)ox->dpmem + 15)) & (~0xfUL));
