        sv = vmaxq_f32(sv, vreinterpretq_f32_u32(vandq_u32(vcgtq_f32(*tp, zerov), vreinterpretq_u32_f32(vaddq_f32(ipv, *tp))))); tp++;
        sv = vmaxq_f32(sv, vreinterpretq_f32_u32(vandq_u32(vcgtq_f32(*tp, zerov), vreinterpretq_u32_f32(vaddq_f32(dpv, *tp))))); tp++;
        sv = vaddq_f32(sv, *ppp); ppp+=2;
