        sv = vreinterpretq_f32_u32(vandq_u32(vcgtq_f32(*tp, zerov), vreinterpretq_u32_f32(vaddq_f32(mpv, *tp)))); tp++;
        sv = vmaxq_f32(sv, vreinterpretq_f32_u32(vandq_u32(vcgtq_f32(*tp, zerov), vreinterpretq_u32_f32(vaddq_f32(ipv, *tp))))); tp++;
        IMO(dpc,q) = vaddq_f32(sv, *ppp); ppp++;
      }

      dcv = esl_neon_right_shift_float(dcv, infv);
      tp = &(om->tfv[7*Q]);
      for (q = 0; q < Q; q++) {
        DMO(dpc, q) = vmaxq_f32(dcv, DMO(dpc, q));
        dcv = vreinterpretq_f32_u32(vandq_u32(vcgtq_f32(*tp, zerov), vreinterpretq_u32_f32(vaddq_f32(DMO(dpc,q), *tp)))); tp++;
      }

