int
p7_OATrace(const P7_OPROFILE *om, const P7_OMX *pp, const P7_OMX *ox, P7_TRACE *tr)
{
  int   i   = ox->L;
  int   k   = 0;
  int   s0, s1;
  float post_prob;
  int   status;

  if (tr->N != 0) return eslEINVAL;

  if ((status = p7_trace_AppendWithPP(tr, p7T_T, k, i, 0.0)) != eslOK) return status;
  if ((status = p7_trace_AppendWithPP(tr, p7T_C, k, i, 0.0)) != eslOK) return status;
  s0 = tr->st[tr->N-1];

  while (s0 != p7T_S)
    {
      switch (s0) {
      case p7T_M: s1 = select_m(om, ox, i, k); k--; i--; break;
      case p7T_D: s1 = select_d(om, ox, i, k); k--;      break;
      case p7T_I: s1 = select_i(om, ox, i, k);      i--; break;
      case p7T_N: s1 = select_n(i);               break;
      case p7T_C: s1 = select_c(om, pp, ox, i);    break;
      case p7T_J: s1 = select_j(om, pp, ox, i);    break;
      case p7T_E: s1 = select_e(om, ox, i, &k);    break;
      case p7T_B: s1 = select_b(om, ox, i);        break;
      default: return eslEINVAL;
      }

      if (s1 == -1) return eslEINVAL;
      post_prob = get_post_prob(pp, s1, s0, k, i);

      if ((status = p7_trace_AppendWithPP(tr, s1, k, i, post_prob)) != eslOK) return status;
      if (s1 == p7T_N || s1 == p7T_J || s1 == p7T_C || s1 == p7T_S) i--;
      s0 = s1;
    }
  tr->M = om->M;
  tr->L = ox->L;
  return p7_trace_Reverse(tr);
}

static inline float
get_post_prob(const P7_OMX *pp, int s_curr, int s_prv, int k, int i)
{
  int Q = p7O_NQ_F(pp->M);
  int q   = (k-1) / Q;
  int r   = (k-1) % Q;
  union { float32x4_t v; float p4[4]; } u;
  switch (s_curr) {
    case p7T_M: u.v = MMO(pp->dpf[i], q); return u.p4[r];
    case p7T_I: u.v = IMO(pp->dpf[i], q); return u.p4[r];
    case p7T_N: if (s_prv == s_curr) return pp->xmx[i*p7X_NXCELLS+p7XN];
    case p7T_C: if (s_prv == s_curr) return pp->xmx[i*p7X_NXCELLS+p7XC];
    case p7T_J: if (s_prv == s_curr) return pp->xmx[i*p7X_NXCELLS+p7XJ];
    default: return 0.0;
  }
}

static inline int
select_m(const P7_OPROFILE *om, const P7_OMX *ox, int i, int k)
{
    int Q = p7O_NQ_F(ox->M);
    int q   = (k-1) / Q;
    int r   = (k-1) % Q;

    float32x4_t *tp = &(om->tfv[7*q]);
    float32x4_t xBv = vmovq_n_f32(ox->xmx[(i-1)*p7X_NXCELLS+p7XB]);
    float32x4_t zerov = vmovq_n_f32(0.0);
    float32x4_t mpv, dpv, ipv;
    union { float32x4_t v; float p4[4]; } u, tv;

    float path[4];
    int   state[4] = {p7T_M, p7T_I, p7T_D, p7T_B};

    if (q == 0) {
      mpv = ox->dpf[i-1][q-1][3*p7X_M];
      dpv = ox->dpf[i-1][q-1][3*p7X_D];
      ipv = ox->dpf[i-1][q-1][3*p7X_I];
    } else {
      mpv = esl_neon_right_shift_float(ox->dpf[i-1][Q-1][3*p7X_M], zerov);
      dpv = esl_neon_right_shift_float(ox->dpf[i-1][Q-1][3*p7X_D], zerov);
      ipv = esl_neon_right_shift_float(ox->dpf[i-1][Q-1][3*p7X_I], zerov);
    }
    u.v = xBv; tv.v = *tp; path[3] = (tv.p4[r] > 0.0) ? -eslINFINITY : u.p4[r] + *tp++;
    u.v = mpv; tv.v = *tp; path[0] = (tv.p4[r] > 0.0) ? -eslINFINITY : u.p4[r] + *tp++;
    u.v = ipv; tv.v = *tp; path[1] = (tv.p4[r] > 0.0) ? -eslINFINITY : u.p4[r] + *tp++;
    u.v = dpv; tv.v = *tp; path[2] = (tv.p4[r] > 0.0) ? -eslINFINITY : u.p4[r] + *tp;

    return state[esl_vec_FArgMax(path, 4)];
}

static inline int
select_d(const P7_OPROFILE *om, const P7_OMX *ox, int i, int k)
{
  int Q = p7O_NQ_F(ox->M);
  int q   = (k-1) / Q;
  int r   = (k-1) % Q;

  float32x4_t zerov = vmovq_n_f32(0.0);
  union { float32x4_t v; float p4[4]; } mpv, dpv, tmdv, tddv;
  float path[2];

  if (q==0) {
    mpv.v = ox->dpf[i][q-1][3*p7X_M];
    dpv.v = ox->dpf[i][q-1][3*p7X_D];
    tmdv.v = om->tfv[7*q-1][p7O_MD];
    tddv.v = om->tfv[7*Q + (q-1)];
  } else {
    mpv.v = esl_neon_right_shift_float( ox->dpf[i][Q-1][3*p7X_M], zerov);
    dpv.v = esl_neon_right_shift_float( ox->dpf[i][Q-1][3*p7X_D], zerov);
    tmdv.v = esl_neon_right_shift_float( om->tfv[7*Q-1][p7O_MD], zerov);
    tddv.v = esl_neon_right_shift_float( om->tfv[8*Q-1], zerov);
  }
  path[0] = (tmdv.p4[r] > 0.0) ? -eslINFINITY : mpv.p4[r];
  path[1] = (tddv.p4[r] > 0.0) ? -eslINFINITY : dpv.p4[r];

  return (path[0] > path[1]) ? p7T_M : p7T_D;
}

static inline int
select_i(const P7_OPROFILE *om, const P7_OMX *ox, int i, int k)
{
  int Q = p7O_NQ_F(ox->M);
  int q   = (k-1) / Q;
  int r   = (k-1) % Q;
  float32x4_t *tp = &(om->tfv[7*q + p7O_MI]);
  union { float32x4_t v; float p4[4]; } tv, mpv, ipv;
  float path[2];

  mpv.v = ox->dpf[i-1][q][3*p7X_M]; tv.v = *tp; path[0] = (tv.p4[r] > 0.0) ? -eslINFINITY : mpv.p4[r] + *tp++;
  ipv.v = ox->dpf[i-1][q][3*p7X_I]; tv.v = *tp; path[1] = (tv.p4[r] > 0.0) ? -eslINFINITY : ipv.p4[r] + *tp;

  return (path[0] > path[1]) ? p7T_M : p7T_I;
}

static inline int
select_n(int i)
{
  return (i==0) ? p7T_S : p7T_N;
}

static inline int
select_c(const P7_OPROFILE *om, const P7_OMX *pp, const P7_OMX *ox, int i)
{
  float path[2];
  path[0] = (om->xf[p7O_C][p7O_LOOP] > 0.0) ? -eslINFINITY : ox->xmx[(i-1)*p7X_NXCELLS+p7XC] + pp->xmx[i*p7X_NXCELLS+p7XC];
  path[1] = (om->xf[p7O_E][p7O_MOVE] > 0.0) ? -eslINFINITY : ox->xmx[  i  *p7X_NXCELLS+p7XE];
  return (path[0] > path[1]) ? p7T_C : p7T_E;
}

static inline int
select_j(const P7_OPROFILE *om, const P7_OMX *pp, const P7_OMX *ox, int i)
{
  float path[2];
  path[0] = (om->xf[p7O_J][p7O_LOOP] > 0.0) ? -eslINFINITY : ox->xmx[(i-1)*p7X_NXCELLS+p7XJ] + pp->xmx[i*p7X_NXCELLS+p7XJ];
  path[1] = (om->xf[p7O_E][p7O_LOOP] > 0.0) ? -eslINFINITY : ox->xmx[  i  *p7X_NXCELLS+p7XE];
  return (path[0] > path[1]) ? p7T_J : p7T_E;
}

static inline int
select_e(const P7_OPROFILE *om, const P7_OMX *ox, int i, int *ret_k)
{
  int Q = p7O_NQ_F(ox->M);
  float32x4_t *dp = ox->dpf[i];
  union { float32x4_t v; float p4[4]; } u;
  float max = -eslINFINITY;
  int   s_max, k_max;
  int   q,r;

  for (q=0; q<Q; q++) {
    u.v = *dp++; dp++;
    for(r=0; r<4; r++) { if (u.p4[r] > max) { max = u.p4[r]; s_max = p7T_M; k_max = r*Q+q+1; }}
    u.v = *dp++; dp+=2;
    for(r=0; r<4; r++) { if (u.p4[r] > max) { max = u.p4[r]; s_max = p7T_D; k_max = r*Q+q+1; }}
  }
  *ret_k = k_max;
  return s_max;
}

static inline int
select_b(const P7_OPROFILE *om, const P7_OMX *ox, int i)
{
  float path[2];
  path[0] = (om->xf[p7O_N][p7O_MOVE] > 0.0) ? -eslINFINITY : ox->xmx[i*p7X_NXCELLS+p7XN];
  path[1] = (om->xf[p7O_J][p7O_MOVE] > 0.0) ? -eslINFINITY : ox->xmx[i*p7X_NXCELLS+p7XJ];
  return (path[0] > path[1]) ? p7T_N : p7T_J;
}
