  if (Q > ox->alloc_Q16) return eslEINVAL;
  ox->M = om->M;

  status = p7_SSVFilter(dsq, L, om, ret_sc);
  if (status != eslENORESULT) return status;

  biasv = vmovq_n_u8(om->bias);
  for (q = 0; q < Q; q++) dp[q] = vmovq_n_u8(0);
  xJ = 0;

  ceilingv = vceqq_u8(biasv,biasv);
  basev = vmovq_n_u8(om->baseb);
  tjbmv = vmovq_n_u8(om->tjb_b - om->tbm_b);
  tecv  = vmovq_n_u8(om->tec_b);
  xJv   = vqsub_u8(biasv, biasv);
  xBv   = vqsub_u8(basev, tjbmv);

  for (i = 1; i <= L; i++)
    {
      rsc = om->rbv[dsq[i]];
      xEv = vmovq_n_u8(0);

      mpv = vextq_u8(zerov, dp[Q-1], 15);

      for (q = 0; q < Q; q++)
      {
        sv = vmax_u8(mpv, xBv);
        sv = vqadd_u8(sv, biasv);
        sv = vqsub_u8(sv, *rsc);  rsc++;
        xEv = vmax_u8(xEv, sv);

        mpv = dp[q];
        dp[q] = sv;
      }
      tempv = vqadd_u8(xEv, biasv);
      tempv = vceqq_u8(tempv, ceilingv);
      cmp = esl_neon_hmax_u8(tempv);

      xEv = vmovq_n_u8(esl_neon_hmax_u8(xEv));

      if (cmp != 0) {
        *ret_sc = eslINFINITY;
        return eslERANGE;
      }
      xEv = vqsub_u8(xEv, tecv);
      xJv = vmax_u8(xJv,xEv);
      xBv = vmax_u8(basev, xJv);
      xBv = vqsub_u8(xBv, tjbmv);
    }

  xJ = (uint8_t)vgetq_lane_s16(vreinterpretq_s16_u8(xJv), 0);
  *ret_sc  = (float) (xJ - om->tjb_b - (float)om->baseb);
  *ret_sc /= om->scale_b;
  *ret_sc -= 3.0;

  return eslOK;
}

int
p7_SSVFilter_longtarget(const ESL_DSQ *dsq, int L, P7_OPROFILE *om, P7_OMX *ox, const P7_SCOREDATA *ssvdata, P7_BG *bg, double P, P7_HMM_WINDOWLIST *windowlist)
{

  register uint8x16_t mpv;
  register uint8x16_t xEv;
  register uint8x16_t xBv;
  register uint8x16_t sv;
  register uint8x16_t biasv;
  int i;
  int q;
  int Q = p7O_NQ_B(om->M);
  uint8x16_t *dp = ox->dpb[0];
  uint8x16_t *rsc;

  uint8x16_t tjbmv;
  uint8x16_t basev;
  uint8x16_t ceilingv;
  uint8x16_t tempv;
  uint8x16_t zerov;
  int cmp;

  int k;
  int n;
  int end;
  int rem_sc;
  int start;
  int target_end;
  int target_start;
  int max_end;
  int max_sc;
  int sc;
  int poss_since_max;
  float ret_sc;

  union { uint8x16_t v; uint8_t b16[16]; } u;
  zerov = vmovq_n_u8(0);


  float null_sc;
  uint8x16_t sc_thresh_v;
  uint8_t sc_thresh;
  float invP;

  if (Q > ox->alloc_Q16) return eslEINVAL;

  ox->M = om->M;
  p7_bg_SetLength(bg, om->max_length);
  p7_oprofile_ReconfigMSVLength(om, om->max_length);
  p7_bg_NullOne(bg, dsq, om->max_length, &null_sc);
  invP = esl_gumbel_inv_surv(P, om->evparam[p7_MMU], om->evparam[p7_MLAMBDA]);

  sc_thresh = (int) ceil( ( (null_sc + invP) / eslCONST_LOG2 + 3.0) * om->scale_b + om->baseb + om->tec_b + om->tjb_b );
  sc_thresh_v = vmovq_n_u8(255-sc_thresh);


  biasv = vmovq_n_u8(om->bias);
  ceilingv = vceqq_u8(biasv,biasv);
  for (q = 0; q < Q; q++) dp[q] = vmovq_n_u8(0);

  basev = vmovq_n_u8(om->baseb);
  tjbmv = vmovq_n_u8(om->tjb_b - om->tbm_b);
  xBv   = vqsub_u8(basev, tjbmv);

  for (i = 1; i <= L; i++)
  {
      rsc = om->rbv[dsq[i]];
      xEv = vmovq_n_u8(0);

      mpv = vextq_u8(zerov, dp[Q-1], 15);
      for (q = 0; q < Q; q++)
      {
        sv = vmax_u8(mpv, xBv);
        sv = vqadd_u8(sv, biasv);
        sv = vqsub_u8(sv, *rsc);  rsc++;
        xEv = vmax_u8(xEv, sv);

        mpv = dp[q];
        dp[q] = sv;
      }
      tempv = vqadd_u8(xEv, sc_thresh_v);
      tempv = vceqq_u8(tempv, ceilingv);
      cmp = esl_neon_hmax_u8(tempv);

      if (cmp != 0) {
        end = -1;
        rem_sc = -1;
        for (q = 0; q < Q; q++) {
          u.v = dp[q];
          for(k=0; k<16; k++) {
            if (u.b16[k] > sc_thresh && u.b16[k] > rem_sc ) {
              if (q*16 + k + 1 <= om->M) {
                end = q*16 + k + 1;
                rem_sc = u.b16[k];
              }
            }
          }
          dp[q] = vmovq_n_u8(0);
        }
        start = end;
        target_end = target_start = i;
        sc = rem_sc;
        while(sc > om->baseb - om->tjb_b - om->tbm_b){
            sc -= (om->bias - ssvdata->ssv_scores[start * om->abc->Kp + dsq[target_start]]);
            --start;
            --target_start;
        }
        start++; target_start++;

        k = end + 1;
        n = target_end + 1;
        max_end = target_end;
        max_sc = sc;
        poss_since_max = 0;
        while(k <= om->M && n <= L){
            sc += om->bias - ssvdata->ssv_scores[k * om->abc->Kp + dsq[n]];
            if(sc > max_sc){
                max_sc = sc;
                max_end = n;
                poss_since_max = 0;
            }
            else{
                poss_since_max++;
                if(poss_since_max > 5)
                    break;
            }
            k++;
            n++;
        }
        end += (max_end - target_end);
        target_end = max_end;
        ret_sc  = (float) (max_sc - om->tjb_b - (float)om->baseb);
        ret_sc /= om->scale_b;
        ret_sc -= 3.0;

        p7_hmmwindow_new(windowlist, 0, target_start, 0, end, end-start+1, ret_sc, p7_NOCOMPLEMENT, L);
        i = target_end;
      }
  }

  return eslOK;
}
